/// Raven `G_ReflectMissile`.
///
/// Reflect the missile roughly back at it's owner.
/// Source: `oracle/codemp/game/g_missile.c:24-89`
pub fn G_ReflectMissile(ctx: &mut GameContext, ent: EntityId, missile: EntityId, forward: vec3_t) {
    let mut bounce_dir: vec3_t = [0.0; 3];

    // Raven resolves an `owner` pointer here only to null-test it below; the
    // test is vacuously true (always a live entity), so the walk is dropped.

    // Check if original owner is bouncing the missile
    let ent_number = ctx.entity(ent).s.number;
    let isowner = ctx.entity(missile).r.ownerNum == ent_number;

    // Save the original speed
    let mut speed = VectorNormalize(&mut ctx.entity_mut(missile).s.pos.trDelta);

    let missile_weapon = ctx.entity(missile).s.weapon;

    // Determine bounce direction
    if missile_weapon != WP_SABER && missile_weapon != G2_MODEL_PART && !isowner {
        // Bounce back at them if you can
        let missile_owner_num = ctx.entity(missile).r.ownerNum;
        let missile_owner_origin = ctx
            .entity(EntityId(missile_owner_num as u32))
            .r
            .currentOrigin;
        let missile_origin = ctx.entity(missile).r.currentOrigin;
        _VectorSubtract(missile_owner_origin, missile_origin, &mut bounce_dir);
        VectorNormalize(&mut bounce_dir);
    } else if isowner {
        // Push the missile away from owner with boost — up the velocity.
        let mut missile_dir: vec3_t = [0.0; 3];
        speed *= 1.5;
        let missile_origin = ctx.entity(missile).r.currentOrigin;
        let ent_origin = ctx.entity(ent).r.currentOrigin;
        _VectorSubtract(missile_origin, ent_origin, &mut missile_dir);
        bounce_dir = ctx.entity(missile).s.pos.trDelta;
        let dot = _DotProduct(forward, missile_dir);
        _VectorScale(bounce_dir, dot, &mut bounce_dir);
        VectorNormalize(&mut bounce_dir);
    } else {
        // Default deflection
        let mut missile_dir: vec3_t = [0.0; 3];
        let ent_origin = ctx.entity(ent).r.currentOrigin;
        let missile_origin = ctx.entity(missile).r.currentOrigin;
        _VectorSubtract(ent_origin, missile_origin, &mut missile_dir);
        bounce_dir = ctx.entity(missile).s.pos.trDelta;
        let dot = _DotProduct(forward, missile_dir);
        _VectorScale(bounce_dir, dot, &mut bounce_dir);
        VectorNormalize(&mut bounce_dir);
    }

    // Add randomness
    for i in 0..3 {
        bounce_dir[i] += RandFloat(ctx, -0.2, 0.2);
    }

    VectorNormalize(&mut bounce_dir);
    let level_time = ctx.world.level.time;
    let m = ctx.entity_mut(missile);
    _VectorScale(bounce_dir, speed, &mut m.s.pos.trDelta);
    m.s.pos.trTime = level_time;
    m.s.pos.trBase = m.r.currentOrigin;

    if missile_weapon != WP_SABER && missile_weapon != G2_MODEL_PART {
        m.r.ownerNum = ent_number;
    }

    if missile_weapon == WP_ROCKET_LAUNCHER {
        m.think = FnId::NONE;
        m.nextthink = 0;
    }
}

/// Raven `G_DeflectMissile`.
///
/// Source: `oracle/codemp/game/g_missile.c:91-140`
pub fn G_DeflectMissile(ctx: &mut GameContext, ent: EntityId, missile: EntityId, forward: vec3_t) {
    let mut bounce_dir: vec3_t = [0.0; 3];
    let mut missile_dir: vec3_t = [0.0; 3];

    // Raven computes the owner check here but never uses it in this fn.
    let _isowner = ctx.entity(missile).r.ownerNum == ctx.entity(ent).s.number;

    // Save the original speed
    let speed = VectorNormalize(&mut ctx.entity_mut(missile).s.pos.trDelta);

    // `client` is a raw `gentity_t*` seam field (§D5) — the gclient deref stays
    // unsafe; the entity walk is by handle.
    let ent_client = ctx.entity(ent).client;
    if !ent_client.is_null() {
        AngleVectors(
            unsafe { (*(ent_client as *mut gclient_t)).ps.viewangles },
            Some(&mut missile_dir),
            None,
            None,
        );
        bounce_dir = missile_dir;
        let dot = _DotProduct(forward, missile_dir);
        _VectorScale(bounce_dir, dot, &mut bounce_dir);
        VectorNormalize(&mut bounce_dir);
    } else {
        bounce_dir = forward;
        VectorNormalize(&mut bounce_dir);
    }

    // Add randomness
    for i in 0..3 {
        bounce_dir[i] += RandFloat(ctx, -1.0, 1.0);
    }

    VectorNormalize(&mut bounce_dir);
    let level_time = ctx.world.level.time;
    let ent_number = ctx.entity(ent).s.number;
    let m = ctx.entity_mut(missile);
    _VectorScale(bounce_dir, speed, &mut m.s.pos.trDelta);
    m.s.pos.trTime = level_time;
    m.s.pos.trBase = m.r.currentOrigin;

    let missile_weapon = m.s.weapon;
    if missile_weapon != WP_SABER && missile_weapon != G2_MODEL_PART {
        m.r.ownerNum = ent_number;
    }

    if missile_weapon == WP_ROCKET_LAUNCHER {
        m.think = FnId::NONE;
        m.nextthink = 0;
    }
}

/// Raven `G_BounceMissile`.
///
/// Source: `oracle/codemp/game/g_missile.c:148-205`
pub fn G_BounceMissile(ctx: &mut GameContext, ent: EntityId, trace: &trace_t) {
    let mut velocity: vec3_t = [0.0; 3];
    let tr = trace;

    // Reflect the velocity on the trace plane
    let (prev_time, time) = {
        let level = &ctx.world.level;
        (level.previousTime, level.time)
    };
    let hitTime = prev_time as c_float + (time - prev_time) as c_float * tr.fraction;
    mp_bg::bg_misc::BG_EvaluateTrajectoryDelta(
        &ctx.entity(ent).s.pos,
        hitTime as c_int,
        &mut velocity,
    );
    let dot = _DotProduct(velocity, tr.plane.normal);
    _VectorMA(
        velocity,
        -2.0 * dot,
        tr.plane.normal,
        &mut ctx.entity_mut(ent).s.pos.trDelta,
    );

    if (ctx.entity(ent).flags & FL_BOUNCE_SHRAPNEL) != 0 {
        let m = ctx.entity_mut(ent);
        let trdelta = m.s.pos.trDelta;
        _VectorScale(trdelta, 0.25, &mut m.s.pos.trDelta);
        m.s.pos.trType = TR_GRAVITY;

        // Check for stop. C promotes `normal[2]` to double against the
        // unsuffixed `0.7`.
        if (tr.plane.normal[2] as f64) > 0.7 && ctx.entity(ent).s.pos.trDelta[2] < 40.0 {
            G_SetOrigin(ctx.entity_mut(ent), tr.endpos);
            ctx.entity_mut(ent).nextthink = ctx.world.level.time + 100;
            return;
        }
    } else if (ctx.entity(ent).flags & FL_BOUNCE_HALF) != 0 {
        // Raven: `VectorScale(..., 0.65, ...)` — the unsuffixed `0.65` makes the
        // macro multiply each component in double, narrowed on store.
        let trdelta = ctx.entity(ent).s.pos.trDelta;
        let out = &mut ctx.entity_mut(ent).s.pos.trDelta;
        out[0] = (trdelta[0] as f64 * 0.65) as f32;
        out[1] = (trdelta[1] as f64 * 0.65) as f32;
        out[2] = (trdelta[2] as f64 * 0.65) as f32;
        // Check for stop.
        // `normal[2]` (float) and `VectorLength` (float) promote to double
        // against the unsuffixed `0.2`/`40` in C; the f32-nearest 0.2 exceeds
        // double 0.2, so evaluate in f64 to keep the branch decision.
        if (tr.plane.normal[2] as f64) > 0.2
            && (VectorLength(ctx.entity(ent).s.pos.trDelta) as f64) < 40.0
        {
            G_SetOrigin(ctx.entity_mut(ent), tr.endpos);
            return;
        }
    }

    // Play bounce sound
    let weapon = ctx.entity(ent).s.weapon;
    if weapon == WP_THERMAL {
        let sound_name = format!(
            "sound/weapons/thermal/bounce{}.wav",
            ctx.world.bg_state.rng.Q_irand(1, 2)
        );
        G_Sound(
            ctx,
            Some(ent),
            CHAN_BODY as c_int,
            G_SoundIndex(&sound_name),
        );
    } else if weapon == WP_SABER {
        let sound_name = format!(
            "sound/weapons/saber/bounce{}.wav",
            ctx.world.bg_state.rng.Q_irand(1, 3)
        );
        G_Sound(
            ctx,
            Some(ent),
            CHAN_BODY as c_int,
            G_SoundIndex(&sound_name),
        );
    }

    let level_time = ctx.world.level.time;
    let m = ctx.entity_mut(ent);
    let current_origin = m.r.currentOrigin;
    _VectorAdd(current_origin, tr.plane.normal, &mut m.r.currentOrigin);
    m.s.pos.trBase = m.r.currentOrigin;
    m.s.pos.trTime = level_time;

    if m.bounceCount != -5 {
        m.bounceCount -= 1;
    }
}

/// Raven `G_ExplodeMissile`.
///
/// Explode a missile without an impact.
/// Source: `oracle/codemp/game/g_missile.c:215-257`
pub fn G_ExplodeMissile(ctx: &mut GameContext, ent: EntityId) {
    let mut dir: vec3_t = [0.0, 0.0, 1.0];
    let mut origin: vec3_t = [0.0; 3];

    let time = ctx.world.level.time;
    mp_bg::bg_misc::BG_EvaluateTrajectory(&ctx.entity(ent).s.pos, time, &mut origin);
    snap_vector(&mut origin);
    G_SetOrigin(ctx.entity_mut(ent), origin);

    let m = ctx.entity_mut(ent);
    m.s.eType = ET_GENERAL as c_int;
    G_AddEvent(m, EV_MISSILE_MISS as c_int, DirToByte(dir));

    let m = ctx.entity_mut(ent);
    m.freeAfterEvent = qtrue;
    m.takedamage = qfalse;

    // Splash damage
    if ctx.entity(ent).splashDamage != 0 {
        // Check if we need to set parent for damage credit. (`s.eType` was just
        // set to ET_GENERAL above, so this ET_MISSILE test never fires —
        // faithful to Raven.)
        if ctx.entity(ent).s.eType == ET_MISSILE as c_int
            && ((ctx.entity(ent).s.eFlags & EF_JETPACK_ACTIVE) != 0)
            && (ctx.entity(ent).r.ownerNum as usize) < MAX_CLIENTS
        {
            let owner_num = ctx.entity(ent).r.ownerNum;
            ctx.entity_mut(ent).parent = Some(EntityId(owner_num as u32));
        }

        let parent = ctx.entity(ent).parent;
        let currentOrigin = ctx.entity(ent).r.currentOrigin;
        let splashDamage = ctx.entity(ent).splashDamage;
        let splashRadius = ctx.entity(ent).splashRadius;
        let splashMod = ctx.entity(ent).splashMethodOfDeath;
        if G_RadiusDamage(
            ctx,
            currentOrigin,
            parent,
            splashDamage as f32,
            splashRadius as f32,
            Some(ent),
            Some(ent),
            splashMod,
        ) {
            if let Some(parent_id) = parent {
                let client = ctx.entity(parent_id).client;
                // §19: oracle derefs `parent->...client->accuracy_hits++`
                // unconditionally (UB if the parent is a non-client entity); guard it.
                // Source: `oracle/codemp/game/g_missile.c:245-252`
                if !client.is_null() {
                    unsafe {
                        (*(client as *mut gclient_t)).accuracy_hits += 1;
                    }
                }
            } else if let Some(activator_id) = ctx.entity(ent).activator {
                let client = ctx.entity(activator_id).client;
                if !client.is_null() {
                    unsafe {
                        (*(client as *mut gclient_t)).accuracy_hits += 1;
                    }
                }
            }
        }
    }

    trap::LinkEntity(
        ctx.engine,
        mp_abi::game::syscalls::G_LINKENTITY::GLinkentityArgs::new(
            core::ptr::from_mut(ctx.entity_mut(ent)).cast(),
        ),
    );
}

/// Raven `G_RunStuckMissile`.
///
/// Source: `oracle/codemp/game/g_missile.c:259-277`
pub fn G_RunStuckMissile(ctx: &mut GameContext, ent: EntityId) {
    if ctx.entity(ent).takedamage != 0 {
        let ground = ctx.entity(ent).s.groundEntityNum;
        if ground >= 0 && (ground as usize) < ENTITYNUM_WORLD as usize {
            let other = EntityId(ground as u32);

            let delta_moving = !VectorCompare(vec3_origin, ctx.entity(other).s.pos.trDelta)
                && ctx.entity(other).s.pos.trType != TR_STATIONARY;
            let apos_moving = !VectorCompare(vec3_origin, ctx.entity(other).s.apos.trDelta)
                && ctx.entity(other).s.apos.trType != TR_STATIONARY;

            if delta_moving || apos_moving {
                // Thing I stuck to is moving or rotating now, kill me
                G_Damage(
                    ctx,
                    Some(ent),
                    Some(other),
                    Some(other),
                    None,
                    vec3_origin,
                    99999,
                    0,
                    MOD_CRUSH as c_int,
                );
                return;
            }
        }
    }
    // Check think function
    G_RunThink(ctx, ent);
}

/// Raven `G_BounceProjectile`.
///
/// Source: `oracle/codemp/game/g_missile.c:284-294`
pub fn G_BounceProjectile(start: vec3_t, impact: vec3_t, dir: vec3_t, endout: &mut [f32; 3]) {
    let mut v: vec3_t = [0.0; 3];
    let mut newv: vec3_t = [0.0; 3];

    _VectorSubtract(impact, start, &mut v);
    let dot = _DotProduct(v, dir);
    _VectorMA(v, -2.0 * dot, dir, &mut newv);

    VectorNormalize(&mut newv);
    _VectorMA(impact, 8192.0, newv, endout);
}

/// Raven `CreateMissile`.
///
/// Source: `oracle/codemp/game/g_missile.c:298-329`
pub fn CreateMissile(
    ctx: &mut GameContext,
    org: vec3_t,
    dir: vec3_t,
    vel: f32,
    life: c_int,
    owner: EntityId,
    altFire: bool,
) -> EntityId {
    let missile = G_Spawn(ctx);

    let level_time = ctx.world.level.time;
    let owner_number = ctx.entity(owner).s.number;
    let mut snapped_org = org;
    snap_vector(&mut snapped_org);

    let e = ctx.entity_mut(missile);
    e.nextthink = level_time + life;
    e.think = Some(EntThink::G_FreeEntity).into();
    e.s.eType = ET_MISSILE as c_int;
    e.r.svFlags = SVF_USE_CURRENT_ORIGIN;
    e.parent = Some(owner);
    e.r.ownerNum = owner_number;

    if altFire {
        e.s.eFlags |= EF_ALT_FIRING;
    }

    e.s.pos.trType = TR_LINEAR;
    e.s.pos.trTime = level_time;
    e.target_ent = None;

    e.s.pos.trBase = snapped_org;
    _VectorScale(dir, vel, &mut e.s.pos.trDelta);
    e.r.currentOrigin = snapped_org;
    snap_vector(&mut e.s.pos.trDelta);

    missile
}

/// Raven `G_MissileBounceEffect`.
///
/// Source: `oracle/codemp/game/g_missile.c:331-354`
pub fn G_MissileBounceEffect(ctx: &mut GameContext, ent: EntityId, org: vec3_t, dir: vec3_t) {
    //FIXME: have an EV_BOUNCE_MISSILE event that checks the s.weapon and does the appropriate effect
    match ctx.entity(ent).s.weapon {
        WP_BOWCASTER => {
            let fx = G_EffectIndex("bowcaster/deflect");
            let currentOrigin = ctx.entity(ent).r.currentOrigin;
            G_PlayEffectID(fx, currentOrigin, dir);
        }
        WP_BLASTER | WP_BRYAR_PISTOL => {
            let fx = G_EffectIndex("blaster/deflect");
            let currentOrigin = ctx.entity(ent).r.currentOrigin;
            G_PlayEffectID(fx, currentOrigin, dir);
        }
        _ => {
            let te = G_TempEntity(ctx, org, EV_SABER_BLOCK as c_int);
            let te = ctx.entity_mut(te);
            te.s.origin = org;
            te.s.angles = dir;
            te.s.eventParm = 0;
            te.s.weapon = 0; //saberNum
            te.s.legsAnim = 0; //bladeNum
        }
    }
}

/// Raven `G_MissileImpact`.
///
/// Source: `oracle/codemp/game/g_missile.c:362-801`
pub fn G_MissileImpact(ctx: &mut GameContext, ent: EntityId, trace: &mut trace_t) {
    // Safe-state 2c: `ent`/`other`/`otherOwner` are `EntityId` handles reached
    // through the `GameContext` accessors; `gclient_t`/`Vehicle_t` seam pointers
    // (read from an entity's `.client`/`.m_pVehicle` field) are NOT arena
    // entities, so those derefs stay raw in tight `unsafe` blocks exactly as
    // Raven does. Each `(*other).client`/`(*ent).client` is re-read at the point
    // of use (never cached across a G_* / trap call), mirroring Raven's per-
    // access field read so no read crosses a mutation.
    let tr: &mut trace_t = trace;
    let other = EntityId(tr.entityNum as u32);
    let mut hitClient = false;
    let mut isKnockedSaber = false;

    // Check for bounce
    if ctx.entity(other).takedamage == 0
        && (ctx.entity(ent).bounceCount > 0 || ctx.entity(ent).bounceCount == -5)
        && (ctx.entity(ent).flags & (FL_BOUNCE | FL_BOUNCE_HALF)) != 0
    {
        G_BounceMissile(ctx, ent, tr);
        G_AddEvent(ctx.entity_mut(ent), EV_GRENADE_BOUNCE as c_int, 0);
        return;
    } else if ctx.entity(ent).neverFree != 0
        && ctx.entity(ent).s.weapon == WP_SABER
        && (ctx.entity(ent).flags & FL_BOUNCE_HALF) != 0
    {
        // This is a knocked-away saber
        if ctx.entity(ent).bounceCount > 0 || ctx.entity(ent).bounceCount == -5 {
            G_BounceMissile(ctx, ent, tr);
            G_AddEvent(ctx.entity_mut(ent), EV_GRENADE_BOUNCE as c_int, 0);
            return;
        }
        isKnockedSaber = true;
    }

    // Bounce shrapnel and force field handling
    if (ctx.entity(other).takedamage == 0
        && (ctx.entity(ent).bounceCount > 0 || ctx.entity(ent).bounceCount == -5)
        && (ctx.entity(ent).flags & FL_BOUNCE_SHRAPNEL) != 0)
        || ((tr.surfaceFlags & SURF_FORCEFIELD) != 0
            && ctx.entity(ent).splashDamage == 0
            && ctx.entity(ent).splashRadius == 0
            && (ctx.entity(ent).bounceCount > 0 || ctx.entity(ent).bounceCount == -5))
    {
        G_BounceMissile(ctx, ent, tr);
        if ctx.entity(ent).bounceCount < 1 {
            ctx.entity_mut(ent).flags &= !FL_BOUNCE_SHRAPNEL;
        }
        return;
    }

    // Saber block checks
    if (ctx.entity(other).r.contents & CONTENTS_LIGHTSABER) != 0 && !isKnockedSaber {
        let otherOwner = EntityId(ctx.entity(other).r.ownerNum as u32);
        if ctx.entity(otherOwner).takedamage != 0
            && !ctx.entity(otherOwner).client.is_null()
            && unsafe { (*ctx.entity(otherOwner).client).ps.duelInProgress } != 0
            && unsafe { (*ctx.entity(otherOwner).client).ps.duelIndex }
                != ctx.entity(ent).r.ownerNum
        {
            // Raven: `goto killProj`.
            missile_kill_proj(ctx, ent, other, tr, hitClient, isKnockedSaber);
            return;
        }
    } else if !isKnockedSaber {
        if ctx.entity(other).takedamage != 0
            && !ctx.entity(other).client.is_null()
            && unsafe { (*ctx.entity(other).client).ps.duelInProgress } != 0
            && unsafe { (*ctx.entity(other).client).ps.duelIndex } != ctx.entity(ent).r.ownerNum
        {
            // Raven: `goto killProj`.
            missile_kill_proj(ctx, ent, other, tr, hitClient, isKnockedSaber);
            return;
        }
    }

    // Heavy weapon deflection check
    if (ctx.entity(other).flags & FL_DMG_BY_HEAVY_WEAP_ONLY) != 0 {
        if ctx.entity(ent).methodOfDeath != MOD_REPEATER_ALT as c_int
            && ctx.entity(ent).methodOfDeath != MOD_ROCKET as c_int
            && ctx.entity(ent).methodOfDeath != MOD_FLECHETTE_ALT_SPLASH as c_int
            && ctx.entity(ent).methodOfDeath != MOD_ROCKET_HOMING as c_int
            && ctx.entity(ent).methodOfDeath != MOD_THERMAL as c_int
            && ctx.entity(ent).methodOfDeath != MOD_THERMAL_SPLASH as c_int
            && ctx.entity(ent).methodOfDeath != MOD_TRIP_MINE_SPLASH as c_int
            && ctx.entity(ent).methodOfDeath != MOD_TIMED_MINE_SPLASH as c_int
            && ctx.entity(ent).methodOfDeath != MOD_DET_PACK_SPLASH as c_int
            && ctx.entity(ent).methodOfDeath != MOD_VEHICLE as c_int
            && ctx.entity(ent).methodOfDeath != MOD_CONC as c_int
            && ctx.entity(ent).methodOfDeath != MOD_CONC_ALT as c_int
            && ctx.entity(ent).methodOfDeath != MOD_SABER as c_int
            && ctx.entity(ent).methodOfDeath != MOD_TURBLAST as c_int
            && ctx.entity(ent).methodOfDeath != MOD_TARGET_LASER as c_int
        {
            // `trace` is a non-null `&mut` reference here; Raven's `!trace` else
            // branch (AngleVectors on other's angles) is dead.
            let fwd: vec3_t = tr.plane.normal;
            G_DeflectMissile(ctx, other, ent, fwd);
            let co = ctx.entity(ent).r.currentOrigin;
            G_MissileBounceEffect(ctx, ent, co, fwd);
            return;
        }
    }

    // Shielded entity deflection
    if (ctx.entity(other).flags & FL_SHIELDED) != 0
        && ctx.entity(ent).s.weapon != WP_ROCKET_LAUNCHER
        && ctx.entity(ent).s.weapon != WP_THERMAL
        && ctx.entity(ent).s.weapon != WP_TRIP_MINE
        && ctx.entity(ent).s.weapon != WP_DET_PACK
        && ctx.entity(ent).s.weapon != WP_DEMP2
        && ctx.entity(ent).s.weapon != WP_EMPLACED_GUN
        && ctx.entity(ent).methodOfDeath != MOD_REPEATER_ALT as c_int
        && ctx.entity(ent).methodOfDeath != MOD_FLECHETTE_ALT_SPLASH as c_int
        && ctx.entity(ent).methodOfDeath != MOD_TURBLAST as c_int
        && ctx.entity(ent).methodOfDeath != MOD_TARGET_LASER as c_int
        && ctx.entity(ent).methodOfDeath != MOD_VEHICLE as c_int
        && ctx.entity(ent).methodOfDeath != MOD_CONC as c_int
        && ctx.entity(ent).methodOfDeath != MOD_CONC_ALT as c_int
        && (ctx.entity(ent).dflags & DAMAGE_HEAVY_WEAP_CLASS) == 0
    {
        let mut fwd: vec3_t = [0.0; 3];
        if !ctx.entity(other).client.is_null() {
            let viewangles = unsafe { (*ctx.entity(other).client).ps.viewangles };
            AngleVectors(viewangles, Some(&mut fwd), None, None);
        } else {
            let ca = ctx.entity(other).r.currentAngles;
            AngleVectors(ca, Some(&mut fwd), None, None);
        }
        G_DeflectMissile(ctx, other, ent, fwd);
        let co = ctx.entity(ent).r.currentOrigin;
        G_MissileBounceEffect(ctx, ent, co, fwd);
        return;
    }

    // Saber block handling
    if ctx.entity(other).takedamage != 0
        && !ctx.entity(other).client.is_null()
        && ctx.entity(ent).s.weapon != WP_ROCKET_LAUNCHER
        && ctx.entity(ent).s.weapon != WP_THERMAL
        && ctx.entity(ent).s.weapon != WP_TRIP_MINE
        && ctx.entity(ent).s.weapon != WP_DET_PACK
        && ctx.entity(ent).s.weapon != WP_DEMP2
        && ctx.entity(ent).methodOfDeath != MOD_REPEATER_ALT as c_int
        && ctx.entity(ent).methodOfDeath != MOD_FLECHETTE_ALT_SPLASH as c_int
        && ctx.entity(ent).methodOfDeath != MOD_CONC as c_int
        && ctx.entity(ent).methodOfDeath != MOD_CONC_ALT as c_int
        && unsafe { (*ctx.entity(other).client).ps.saberBlockTime } < ctx.world.level.time
        && !isKnockedSaber
        && {
            let ent_origin = ctx.entity(ent).r.currentOrigin;
            WP_SaberCanBlock(ctx, Some(other), ent_origin, 0, 0, true, 0)
        } != 0
    {
        let mut fwd: vec3_t = [0.0; 3];
        let otherDefLevel =
            unsafe { (*ctx.entity(other).client).ps.fd.forcePowerLevel[FP_SABER_DEFENSE as usize] };

        let ent_origin = ctx.entity(ent).r.currentOrigin;
        let te_id = G_TempEntity(ctx, ent_origin, EV_SABER_BLOCK as c_int);
        let te = ctx.entity_mut(te_id);
        te.s.origin = ent_origin;
        te.s.angles = tr.plane.normal;
        te.s.eventParm = 0;
        te.s.weapon = 0;
        te.s.legsAnim = 0;

        let mut adjusted_def_level = otherDefLevel;
        if unsafe { (*ctx.entity(other).client).ps.velocity[2] } > 0.0
            || unsafe { (*ctx.entity(other).client).pers.cmd.forwardmove } < 0
        {
            adjusted_def_level -= 1;
            if adjusted_def_level < 0 {
                adjusted_def_level = 0;
            }
        }

        let viewangles = unsafe { (*ctx.entity(other).client).ps.viewangles };
        AngleVectors(viewangles, Some(&mut fwd), None, None);
        if adjusted_def_level == FORCE_LEVEL_1 as c_int {
            // Kill the projectile
        } else if adjusted_def_level == FORCE_LEVEL_2 as c_int {
            G_DeflectMissile(ctx, other, ent, fwd);
        } else {
            G_ReflectMissile(ctx, other, ent, fwd);
        }
        unsafe {
            (*ctx.entity(other).client).ps.saberBlockTime =
                ctx.world.level.time + (350 - (adjusted_def_level * 100));
            (*ctx.entity(other).client).ps.saberEventFlags |= SEF_DEFLECTED;
        }

        if adjusted_def_level == FORCE_LEVEL_3 as c_int {
            unsafe {
                (*ctx.entity(other).client).ps.saberBlockTime = 0;
            }
        }

        // Raven: FORCE_LEVEL_1 is `goto killProj` — it skips the sticky-missile
        // and impact-damage sections. Source: `oracle/codemp/game/g_missile.c:563-567`
        if adjusted_def_level == FORCE_LEVEL_1 as c_int {
            missile_kill_proj(ctx, ent, other, tr, hitClient, isKnockedSaber);
        }
        return;
    } else if (ctx.entity(other).r.contents & CONTENTS_LIGHTSABER) != 0 && !isKnockedSaber {
        let otherOwner = EntityId(ctx.entity(other).r.ownerNum as u32);
        if ctx.entity(otherOwner).takedamage != 0
            && !ctx.entity(otherOwner).client.is_null()
            && ctx.entity(ent).s.weapon != WP_ROCKET_LAUNCHER
            && ctx.entity(ent).s.weapon != WP_THERMAL
            && ctx.entity(ent).s.weapon != WP_TRIP_MINE
            && ctx.entity(ent).s.weapon != WP_DET_PACK
            && ctx.entity(ent).s.weapon != WP_DEMP2
            && ctx.entity(ent).methodOfDeath != MOD_REPEATER_ALT as c_int
            && ctx.entity(ent).methodOfDeath != MOD_FLECHETTE_ALT_SPLASH as c_int
            && ctx.entity(ent).methodOfDeath != MOD_CONC as c_int
            && ctx.entity(ent).methodOfDeath != MOD_CONC_ALT as c_int
        {
            let mut fwd: vec3_t = [0.0; 3];
            // Deflect it even if we can't actually block it because it hit
            // our saber — triggers the defender's saber-block animation.
            if !ctx.entity(otherOwner).client.is_null()
                && unsafe { (*ctx.entity(otherOwner).client).ps.weaponTime } <= 0
            {
                let co = ctx.entity(ent).r.currentOrigin;
                WP_SaberBlockNonRandom(ctx.entity(otherOwner), co, qtrue);
            }
            let co = ctx.entity(ent).r.currentOrigin;
            let te_id = G_TempEntity(ctx, co, EV_SABER_BLOCK as c_int);
            let te = ctx.entity_mut(te_id);
            te.s.origin = co;
            te.s.angles = tr.plane.normal;
            te.s.eventParm = 0;
            te.s.weapon = 0;
            te.s.legsAnim = 0;

            let mut other_def_level = unsafe {
                (*ctx.entity(otherOwner).client).ps.fd.forcePowerLevel[FP_SABER_DEFENSE as usize]
            };
            if unsafe { (*ctx.entity(otherOwner).client).ps.velocity[2] } > 0.0
                || unsafe { (*ctx.entity(otherOwner).client).pers.cmd.forwardmove } < 0
            {
                other_def_level -= 1;
                if other_def_level < 0 {
                    other_def_level = 0;
                }
            }

            let viewangles = unsafe { (*ctx.entity(otherOwner).client).ps.viewangles };
            AngleVectors(viewangles, Some(&mut fwd), None, None);

            if other_def_level == FORCE_LEVEL_1 as c_int {
                // Kill projectile
            } else if other_def_level == FORCE_LEVEL_2 as c_int {
                G_DeflectMissile(ctx, otherOwner, ent, fwd);
            } else {
                G_ReflectMissile(ctx, otherOwner, ent, fwd);
            }
            unsafe {
                (*ctx.entity(otherOwner).client).ps.saberBlockTime =
                    ctx.world.level.time + (350 - (other_def_level * 100));
                (*ctx.entity(otherOwner).client).ps.saberEventFlags |= SEF_DEFLECTED;
            }

            if other_def_level == FORCE_LEVEL_3 as c_int {
                unsafe {
                    (*ctx.entity(otherOwner).client).ps.saberBlockTime = 0;
                }
            }

            // Raven: FORCE_LEVEL_1 is `goto killProj` — it skips the sticky-missile
            // and impact-damage sections. Source: `oracle/codemp/game/g_missile.c:640-644`
            if other_def_level == FORCE_LEVEL_1 as c_int {
                missile_kill_proj(ctx, ent, other, tr, hitClient, isKnockedSaber);
            }
            return;
        }
    }

    // Sticky missiles
    if ctx.entity(other).takedamage == 0 && (ctx.entity(ent).s.eFlags & EF_MISSILE_STICK) != 0 {
        laserTrapStick(ctx, ent, tr.endpos, tr.plane.normal);
        G_AddEvent(ctx.entity_mut(ent), EV_MISSILE_STICK as c_int, 0);
        return;
    }

    // Impact damage
    if ctx.entity(other).takedamage != 0 && !isKnockedSaber {
        if ctx.entity(ent).damage != 0 {
            let mut velocity: vec3_t = [0.0; 3];
            let mut didDmg = false;

            let owner_num = ctx.entity(ent).r.ownerNum as u32;
            if LogAccuracyHit(ctx, other, Some(EntityId(owner_num))) {
                let owner_client = ctx.entity(EntityId(owner_num)).client;
                unsafe {
                    (*owner_client).accuracy_hits += 1;
                }
                hitClient = true;
            }

            let pos = ctx.entity(ent).s.pos;
            let time = ctx.world.level.time;
            mp_bg::bg_misc::BG_EvaluateTrajectoryDelta(&pos, time, &mut velocity);
            if VectorLength(velocity) == 0.0 {
                velocity[2] = 1.0;
            }

            if ctx.entity(ent).s.weapon == WP_BOWCASTER
                || ctx.entity(ent).s.weapon == WP_FLECHETTE
                || ctx.entity(ent).s.weapon == WP_ROCKET_LAUNCHER
            {
                if ctx.entity(ent).s.weapon == WP_FLECHETTE
                    && (ctx.entity(ent).s.eFlags & EF_ALT_FIRING) != 0
                {
                    // §19: oracle calls `ent->think(ent)` unconditionally (UB if
                    // think is NULL); guard the dispatch.
                    // Source: `oracle/codemp/game/g_missile.c:677`
                    if let Some(think_fn) = ctx.entity(ent).think.get() {
                        // Call the think function
                        let ent_ptr = ctx.entity_mut(ent) as *mut gentity_t;
                        crate::ent_fn_enums::dispatch_think(ctx, think_fn, ent_ptr);
                    }
                } else {
                    let owner = EntityId::from_num(ctx.entity(ent).r.ownerNum);
                    let co = ctx.entity(ent).r.currentOrigin;
                    let dmg = ctx.entity(ent).damage;
                    let mod_ = ctx.entity(ent).methodOfDeath;
                    G_Damage(
                        ctx,
                        Some(other),
                        Some(ent),
                        owner,
                        Some(&mut velocity),
                        co,
                        dmg,
                        DAMAGE_HALF_ABSORB as c_int,
                        mod_,
                    );
                    didDmg = true;
                }
            } else {
                let owner = EntityId::from_num(ctx.entity(ent).r.ownerNum);
                let co = ctx.entity(ent).r.currentOrigin;
                let dmg = ctx.entity(ent).damage;
                let mod_ = ctx.entity(ent).methodOfDeath;
                G_Damage(
                    ctx,
                    Some(other),
                    Some(ent),
                    owner,
                    Some(&mut velocity),
                    co,
                    dmg,
                    0,
                    mod_,
                );
                didDmg = true;
            }

            if didDmg && !ctx.entity(other).client.is_null() {
                let npc_class = unsafe { (*ctx.entity(other).client).NPC_class };
                if npc_class == CLASS_SEEKER
                    || npc_class == CLASS_PROBE
                    || npc_class == CLASS_MOUSE
                    || npc_class == CLASS_GONK
                    || npc_class == CLASS_R2D2
                    || npc_class == CLASS_R5D2
                    || npc_class == CLASS_REMOTE
                    || npc_class == CLASS_MARK1
                    || npc_class == CLASS_MARK2
                    || npc_class == CLASS_INTERROGATOR
                    || npc_class == CLASS_ATST
                    || npc_class == CLASS_SENTRY
                {
                    unsafe {
                        if (*ctx.entity(other).client).ps.electrifyTime < ctx.world.level.time + 100
                        {
                            (*ctx.entity(other).client).ps.electrifyTime =
                                ctx.world.level.time + 450;
                        }
                    }
                }
            }
        }

        if ctx.entity(ent).s.weapon == WP_DEMP2 {
            if !ctx.entity(other).client.is_null()
                && unsafe { (*ctx.entity(other).client).NPC_class } == CLASS_VEHICLE
            {
                let other_vehicle = ctx.entity(other).m_pVehicle;
                if !other_vehicle.is_null()
                    && unsafe { !(*other_vehicle).m_pVehicleInfo.is_null() }
                    && (unsafe { (*(*other_vehicle).m_pVehicleInfo).r#type } == VH_SPEEDER
                        || (unsafe { (*(*other_vehicle).m_pVehicleInfo).r#type } == VH_FIGHTER
                            && !ctx.entity(ent).classname.is_null()
                            && Q_stricmp(
                                &(unsafe { cstr_to_str(ctx.entity(ent).classname) }),
                                "vehicle_proj",
                            ) == 0))
                    && unsafe {
                        FighterIsLanded(other_vehicle, &mut (*ctx.entity(other).client).ps)
                    } == 0
                    && (ctx.entity(other).spawnflags & 2) == 0
                {
                    unsafe {
                        if (*ctx.entity(other).client).ps.electrifyTime > ctx.world.level.time {
                            (*ctx.entity(other).client).ps.electrifyTime +=
                                ctx.world.bg_state.rng.Q_irand(200, 500);
                            if (*ctx.entity(other).client).ps.electrifyTime
                                > ctx.world.level.time + 4000
                            {
                                (*ctx.entity(other).client).ps.electrifyTime =
                                    ctx.world.level.time + 4000;
                            }
                        } else {
                            (*ctx.entity(other).client).ps.electrifyTime =
                                ctx.world.level.time + ctx.world.bg_state.rng.Q_irand(200, 500);
                        }
                    }
                }
            } else if !ctx.entity(other).client.is_null()
                && unsafe { (*ctx.entity(other).client).ps.powerups[PW_CLOAKED as usize] } != 0
            {
                Jedi_Decloak(ctx, Some(other));
                if ctx.entity(ent).methodOfDeath == MOD_DEMP2_ALT as c_int {
                    unsafe {
                        (*ctx.entity(other).client).cloakToggleTime = Q3_INFINITE;
                    }
                } else {
                    unsafe {
                        (*ctx.entity(other).client).cloakToggleTime =
                            ctx.world.level.time + ctx.world.bg_state.rng.Q_irand(3000, 10000);
                    }
                }
            }
        }
    }

    missile_kill_proj(ctx, ent, other, tr, hitClient, isKnockedSaber);
}

/// Split from `G_MissileImpact` — Raven's `killProj` label tail: impact event,
/// endpos snap + origin set, splash damage with accuracy credit, G2-part
/// unfree, and relink. Reached by `goto` from the duel-isolation and
/// FORCE_LEVEL_1 saber-block arms, and by fall-through after impact damage.
/// Source: `oracle/codemp/game/g_missile.c:758-800`
fn missile_kill_proj(
    ctx: &mut GameContext,
    ent: EntityId,
    other: EntityId,
    tr: &mut trace_t,
    hitClient: bool,
    isKnockedSaber: bool,
) {
    // Raven: is it cheaper in bandwidth to just remove this ent and create a
    // new one, rather than changing the missile into the explosion?
    if ctx.entity(other).takedamage != 0 && !ctx.entity(other).client.is_null() && !isKnockedSaber {
        G_AddEvent(
            ctx.entity_mut(ent),
            EV_MISSILE_HIT as c_int,
            DirToByte(tr.plane.normal),
        );
        let n = ctx.entity(other).s.number;
        ctx.entity_mut(ent).s.otherEntityNum = n;
    } else if (tr.surfaceFlags & SURF_METALSTEPS) != 0 {
        G_AddEvent(
            ctx.entity_mut(ent),
            EV_MISSILE_MISS_METAL as c_int,
            DirToByte(tr.plane.normal),
        );
    } else if ctx.entity(ent).s.weapon != G2_MODEL_PART && !isKnockedSaber {
        G_AddEvent(
            ctx.entity_mut(ent),
            EV_MISSILE_MISS as c_int,
            DirToByte(tr.plane.normal),
        );
    }

    if !isKnockedSaber {
        let m = ctx.entity_mut(ent);
        m.freeAfterEvent = qtrue;
        // change over to a normal entity right at the point of impact
        m.s.eType = ET_GENERAL as c_int;
    }

    // save net bandwidth
    let trbase = ctx.entity(ent).s.pos.trBase;
    tr.endpos = SnapVectorTowards(tr.endpos, trbase);
    G_SetOrigin(ctx.entity_mut(ent), tr.endpos);

    ctx.entity_mut(ent).takedamage = qfalse;
    // splash damage (doesn't apply to person directly hit)
    if ctx.entity(ent).splashDamage != 0 {
        let parent_id = ctx.entity(ent).parent;
        let splashDamage = ctx.entity(ent).splashDamage as f32;
        let splashRadius = ctx.entity(ent).splashRadius as f32;
        let splashMod = ctx.entity(ent).splashMethodOfDeath;
        if G_RadiusDamage(
            ctx,
            tr.endpos,
            parent_id,
            splashDamage,
            splashRadius,
            Some(other),
            Some(ent),
            splashMod,
        ) {
            let owner_num = ctx.entity(ent).r.ownerNum as u32;
            let owner_client = ctx.entity(EntityId(owner_num)).client;
            if !hitClient && !owner_client.is_null() {
                unsafe {
                    (*owner_client).accuracy_hits += 1;
                }
            }
        }
    }

    if ctx.entity(ent).s.weapon == G2_MODEL_PART {
        // it will free itself
        ctx.entity_mut(ent).freeAfterEvent = qfalse;
    }

    trap::LinkEntity(
        ctx.engine,
        mp_abi::game::syscalls::G_LINKENTITY::GLinkentityArgs::new(
            core::ptr::from_mut(ctx.entity_mut(ent)).cast(),
        ),
    );
}

/// Raven `G_RunMissile`.
///
/// Source: `oracle/codemp/game/g_missile.c:808-1019`
pub fn G_RunMissile(ctx: &mut GameContext, ent: EntityId) {
    // Safe-state 2c: `ent` is an `EntityId` handle reached through the
    // `GameContext` accessors. The one seam deref is the grapple owner's
    // `gclient_t` (`parent.client`, read from the entity's `.client` field) —
    // not an arena entity, so it stays raw in a tight `unsafe` block.
    let mut origin: vec3_t = [0.0; 3];
    let mut groundSpot: vec3_t = [0.0; 3];
    let mut tr: trace_t = unsafe { std::mem::zeroed() };
    let mut passent: c_int;
    let mut isKnockedSaber = false;

    if ctx.entity(ent).neverFree != 0
        && ctx.entity(ent).s.weapon == WP_SABER
        && (ctx.entity(ent).flags & FL_BOUNCE_HALF) != 0
    {
        isKnockedSaber = true;
        ctx.entity_mut(ent).s.pos.trType = TR_GRAVITY;
    }

    // Get current position
    let time = ctx.world.level.time;
    mp_bg::bg_misc::BG_EvaluateTrajectory(&ctx.entity(ent).s.pos, time, &mut origin);

    // Determine entity to pass (not collide with)
    if let Some(target_id) = ctx.entity(ent).target_ent {
        passent = ctx.entity(target_id).s.number;
    } else if (ctx.entity(ent).r.svFlags & SVF_OWNERNOTSHARED) != 0
        && (ctx.entity(ent).s.eFlags & EF_JETPACK_ACTIVE) != 0
    {
        // Vehicle missile that should be solid to owner
        passent = ctx.entity(ent).s.number;
    } else {
        passent = ctx.entity(ent).r.ownerNum as c_int;
    }

    // Trace from previous position to current position
    if ctx.world.cvars.d_projectileGhoul2Collision.integer != 0 {
        let clipmask = ctx.entity(ent).clipmask;
        let g2lod = ctx.world.cvars.g_g2TraceLod.integer;
        trap::G2Trace(
            ctx.engine,
            mp_abi::game::syscalls::G_G2TRACE::GG2TraceArgs::new(
                &mut tr,
                &ctx.entity(ent).r.currentOrigin,
                &ctx.entity(ent).r.mins,
                &ctx.entity(ent).r.maxs,
                &origin,
                passent,
                clipmask,
                G2TRFLAG_DOGHOULTRACE
                    | G2TRFLAG_GETSURFINDEX
                    | G2TRFLAG_THICK
                    | G2TRFLAG_HITCORPSES,
                g2lod,
            ),
        );

        if tr.fraction != 1.0 && (tr.entityNum as usize) < ENTITYNUM_WORLD as usize {
            let g2hit = EntityId(tr.entityNum as u32);
            let g2_client = ctx.entity(g2hit).client;
            let g2_ghoul2 = ctx.entity(g2hit).ghoul2;
            if ctx.entity(g2hit).inuse != 0 && !g2_client.is_null() && !g2_ghoul2.is_null() {
                let time = ctx.world.level.time;
                unsafe {
                    (*g2_client).g2LastSurfaceHit = tr.surfaceFlags as c_int;
                    (*g2_client).g2LastSurfaceTime = time;
                }
            }
            if !g2_ghoul2.is_null() {
                tr.surfaceFlags = 0;
            }
        }
    } else {
        let clipmask = ctx.entity(ent).clipmask;
        trap::Trace(
            ctx.engine,
            mp_abi::game::syscalls::G_TRACE::GTraceArgs::new(
                &mut tr,
                &ctx.entity(ent).r.currentOrigin,
                &ctx.entity(ent).r.mins,
                &ctx.entity(ent).r.maxs,
                &origin,
                passent,
                clipmask,
            ),
        );
    }

    if tr.startsolid != 0 || tr.allsolid != 0 {
        // Make sure tr.entityNum is set to the entity we're stuck in
        let clipmask = ctx.entity(ent).clipmask;
        trap::Trace(
            ctx.engine,
            mp_abi::game::syscalls::G_TRACE::GTraceArgs::new(
                &mut tr,
                &ctx.entity(ent).r.currentOrigin,
                &ctx.entity(ent).r.mins,
                &ctx.entity(ent).r.maxs,
                &ctx.entity(ent).r.currentOrigin,
                passent,
                clipmask,
            ),
        );
        tr.fraction = 0.0;
    } else {
        ctx.entity_mut(ent).r.currentOrigin = tr.endpos;
    }

    if ctx.entity(ent).passThroughNum != 0
        && tr.entityNum as u32 == (ctx.entity(ent).passThroughNum - 1) as u32
    {
        ctx.entity_mut(ent).r.currentOrigin = origin;
        trap::LinkEntity(
            ctx.engine,
            mp_abi::game::syscalls::G_LINKENTITY::GLinkentityArgs::new(
                core::ptr::from_mut(ctx.entity_mut(ent)).cast(),
            ),
        );
        // Fall through to passthrough label
    } else {
        trap::LinkEntity(
            ctx.engine,
            mp_abi::game::syscalls::G_LINKENTITY::GLinkentityArgs::new(
                core::ptr::from_mut(ctx.entity_mut(ent)).cast(),
            ),
        );

        if ctx.entity(ent).s.weapon == G2_MODEL_PART && ctx.entity(ent).bounceCount == 0 {
            let mut lowerOrg: vec3_t = [0.0; 3];
            let mut trG: trace_t = unsafe { std::mem::zeroed() };

            lowerOrg = ctx.entity(ent).r.currentOrigin;
            lowerOrg[2] -= 1.0;
            let clipmask = ctx.entity(ent).clipmask;
            trap::Trace(
                ctx.engine,
                mp_abi::game::syscalls::G_TRACE::GTraceArgs::new(
                    &mut trG,
                    &ctx.entity(ent).r.currentOrigin,
                    &ctx.entity(ent).r.mins,
                    &ctx.entity(ent).r.maxs,
                    &lowerOrg,
                    passent,
                    clipmask,
                ),
            );

            groundSpot = trG.endpos;

            if trG.startsolid == 0
                && trG.allsolid == 0
                && trG.entityNum as u32 == ENTITYNUM_WORLD as u32
            {
                ctx.entity_mut(ent).s.groundEntityNum = trG.entityNum as c_int;
            } else {
                ctx.entity_mut(ent).s.groundEntityNum = ENTITYNUM_NONE as c_int;
            }
        }

        if tr.fraction != 1.0 {
            // Never explode or bounce on sky
            if (tr.surfaceFlags & SURF_NOIMPACT) != 0 {
                // If grapple, reset owner. `parent.client` is a `gclient_t*` seam
                // pointer (not an arena entity); the deref stays raw.
                if let Some(parent_id) = ctx.entity(ent).parent {
                    let client_ptr = ctx.entity(parent_id).client;
                    if !client_ptr.is_null() {
                        unsafe {
                            if (*client_ptr).hook == Some(ent) {
                                (*client_ptr).hook = None;
                            }
                        }
                    }
                }

                if (ctx.entity(ent).s.weapon == WP_SABER && ctx.entity(ent).isSaberEntity != 0)
                    || isKnockedSaber
                {
                    G_RunThink(ctx, ent);
                    return;
                } else if ctx.entity(ent).s.weapon != G2_MODEL_PART {
                    G_FreeEntity(ctx, Some(ent));
                    return;
                }
            }

            // Ghoul2 mark handling code is #if 0, so we skip to the active part
            if ctx.entity(ent).s.weapon > WP_NONE as c_int
                && ctx.entity(ent).s.weapon < WP_NUM_WEAPONS as c_int
                && ((tr.entityNum as usize) < MAX_CLIENTS
                    || ctx.entity(EntityId(tr.entityNum as u32)).s.eType == ET_NPC as c_int)
            {
                let m = ctx.entity_mut(ent);
                m.s.origin = m.r.currentOrigin;
                let pos = ctx.entity(ent).s.pos;
                let time = ctx.world.level.time;
                mp_bg::bg_misc::BG_EvaluateTrajectory(
                    &pos,
                    time,
                    &mut ctx.entity_mut(ent).s.origin2,
                );

                if VectorCompare(ctx.entity(ent).s.origin, ctx.entity(ent).s.origin2) {
                    ctx.entity_mut(ent).s.origin2[2] += 2.0;
                }
            }

            G_MissileImpact(ctx, ent, &mut tr);

            if tr.entityNum as u32 == ctx.entity(ent).s.otherEntityNum as u32 {
                ctx.entity_mut(ent).s.trickedentindex = 1;
            }

            if ctx.entity(ent).s.eType != ET_MISSILE as c_int
                && ctx.entity(ent).s.weapon != G2_MODEL_PART
            {
                return; // Exploded
            }
        }
    }

    // passthrough label
    if ctx.entity(ent).s.pos.trType == TR_STATIONARY
        && (ctx.entity(ent).s.eFlags & EF_MISSILE_STICK) != 0
    {
        // Stuck missiles should check some special stuff
        G_RunStuckMissile(ctx, ent);
        return;
    }

    if ctx.entity(ent).s.weapon == G2_MODEL_PART {
        if ctx.entity(ent).s.groundEntityNum == ENTITYNUM_WORLD as c_int {
            let level_time = ctx.world.level.time;
            let m = ctx.entity_mut(ent);
            m.s.pos.trType = TR_LINEAR;
            m.s.pos.trDelta = [0.0; 3];
            m.s.pos.trTime = level_time;

            m.s.pos.trBase = groundSpot;
            m.r.currentOrigin = groundSpot;

            if m.s.apos.trType != TR_STATIONARY {
                m.s.apos.trType = TR_STATIONARY;
                m.s.apos.trTime = level_time;

                m.s.apos.trBase[ROLL as usize] = 0.0;
                m.s.apos.trBase[PITCH as usize] = 0.0;
            }
        }
    }

    // Check think function after bouncing
    G_RunThink(ctx, ent);
}
